$chapters = @"

,  {"id":"SAT-10-06-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A train travels 60 mph for 2.5 hours. Distance covered?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"150 miles"},{"id":"b","text":"120 miles"},{"id":"c","text":"180 miles"},{"id":"d","text":"200 miles"}],"correctOptionId":"a","explanation":"Distance = speed x time = 60 x 2.5 = 150 miles.","difficulty":"Easy"},
  {"id":"SAT-10-06-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"If 5 apples cost $3, how much do 15 apples cost?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"$9"},{"id":"b","text":"$6"},{"id":"c","text":"$12"},{"id":"d","text":"$15"}],"correctOptionId":"a","explanation":"15/5 = 3 times as many, so 3 x $3 = $9.","difficulty":"Easy"},
  {"id":"SAT-10-06-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A rectangle is 3 times as long as it is wide. Perimeter is 48. Width?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"6"},{"id":"b","text":"8"},{"id":"c","text":"12"},{"id":"d","text":"4"}],"correctOptionId":"a","explanation":"Width = w, length = 3w. 2(w + 3w) = 48 -> 8w = 48 -> w = 6.","difficulty":"Easy"},
  {"id":"SAT-10-06-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"John has twice as many books as Mary. Together they have 30. How many does John have?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"20"},{"id":"b","text":"15"},{"id":"c","text":"10"},{"id":"d","text":"25"}],"correctOptionId":"a","explanation":"Mary = m, John = 2m. m + 2m = 30 -> 3m = 30 -> m = 10. John = 20.","difficulty":"Easy"},
  {"id":"SAT-10-06-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A car uses 8 gallons to travel 240 miles. Miles per gallon?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"30"},{"id":"b","text":"25"},{"id":"c","text":"20"},{"id":"d","text":"35"}],"correctOptionId":"a","explanation":"MPG = 240/8 = 30.","difficulty":"Easy"},
  {"id":"SAT-10-06-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"If x + y = 12 and x - y = 4, what is x?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"8"},{"id":"b","text":"4"},{"id":"c","text":"6"},{"id":"d","text":"10"}],"correctOptionId":"a","explanation":"Adding: 2x = 16, x = 8.","difficulty":"Easy"},
  {"id":"SAT-10-06-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A shirt originally $40 is on sale for 25% off. Sale price?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"$30"},{"id":"b","text":"$35"},{"id":"c","text":"$10"},{"id":"d","text":"$45"}],"correctOptionId":"a","explanation":"Discount = 0.25 x 40 = $10. Sale price = 40 - 10 = $30.","difficulty":"Easy"},
  {"id":"SAT-10-06-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"Working together, A completes a job in 6 hours, B in 4 hours. Together?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"2.4 hours"},{"id":"b","text":"5 hours"},{"id":"c","text":"10 hours"},{"id":"d","text":"3 hours"}],"correctOptionId":"a","explanation":"Rate = 1/6 + 1/4 = 2/12 + 3/12 = 5/12. Time = 12/5 = 2.4 hours.","difficulty":"Easy"},
  {"id":"SAT-10-06-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A number increased by 20% is 72. Original number?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"60"},{"id":"b","text":"55"},{"id":"c","text":"65"},{"id":"d","text":"50"}],"correctOptionId":"a","explanation":"1.20x = 72 -> x = 72/1.2 = 60.","difficulty":"Easy"},
  {"id":"SAT-10-06-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"If 3x = 2y and x + y = 10, what is x?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"4"},{"id":"b","text":"6"},{"id":"c","text":"5"},{"id":"d","text":"3"}],"correctOptionId":"a","explanation":"x = 2y/3. 2y/3 + y = 10 -> 5y/3 = 10 -> y = 6. x = 4.","difficulty":"Easy"},
  {"id":"SAT-10-06-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A pot contains 3 red, 5 blue, 2 green balls. Two drawn with replacement. P(both red)?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"9/100"},{"id":"b","text":"3/50"},{"id":"c","text":"1/15"},{"id":"d","text":"6/100"}],"correctOptionId":"a","explanation":"With replacement: (3/10)(3/10) = 9/100.","difficulty":"Medium"},
  {"id":"SAT-10-06-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"Two pipes fill a tank. Pipe A in 6 hours, Pipe B in 4 hours. How long together?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"2.4 hours"},{"id":"b","text":"3 hours"},{"id":"c","text":"5 hours"},{"id":"d","text":"10 hours"}],"correctOptionId":"a","explanation":"Combined rate = 1/6 + 1/4 = 5/12. Time = 12/5 = 2.4 hours.","difficulty":"Medium"},
  {"id":"SAT-10-06-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"The sum of three consecutive integers is 72. Largest?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"25"},{"id":"b","text":"24"},{"id":"c","text":"23"},{"id":"d","text":"26"}],"correctOptionId":"a","explanation":"n + (n+1) + (n+2) = 72 -> 3n + 3 = 72 -> n = 23. Largest = 25.","difficulty":"Medium"},
  {"id":"SAT-10-06-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A map has scale 1 inch = 50 miles. Two cities are 3.5 inches apart. Actual distance?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"175 miles"},{"id":"b","text":"150 miles"},{"id":"c","text":"200 miles"},{"id":"d","text":"125 miles"}],"correctOptionId":"a","explanation":"Distance = 3.5 x 50 = 175 miles.","difficulty":"Medium"},
  {"id":"SAT-10-06-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A invests $1000 at 5% simple interest for 3 years. Interest earned?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"$150"},{"id":"b","text":"$50"},{"id":"c","text":"$100"},{"id":"d","text":"$200"}],"correctOptionId":"a","explanation":"I = Prt = 1000 x 0.05 x 3 = $150.","difficulty":"Medium"},
  {"id":"SAT-10-06-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"If the average of 5 numbers is 20, and 4 of them are 15, 18, 22, 25, what is the 5th?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"20"},{"id":"b","text":"22"},{"id":"c","text":"18"},{"id":"d","text":"25"}],"correctOptionId":"a","explanation":"Sum = 100. 15+18+22+25 = 80. 5th = 100 - 80 = 20.","difficulty":"Medium"},
  {"id":"SAT-10-06-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A tank is 3/4 full. After adding 15 gallons, it is full. Capacity?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"60 gallons"},{"id":"b","text":"45 gallons"},{"id":"c","text":"20 gallons"},{"id":"d","text":"75 gallons"}],"correctOptionId":"a","explanation":"1/4 of tank = 15 gallons. Full tank = 60 gallons.","difficulty":"Medium"},
  {"id":"SAT-10-06-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"Two numbers sum to 50. One is 8 more than the other. Larger number?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"29"},{"id":"b","text":"25"},{"id":"c","text":"21"},{"id":"d","text":"33"}],"correctOptionId":"a","explanation":"x + (x+8) = 50 -> 2x = 42 -> x = 21. Larger = 29.","difficulty":"Medium"},
  {"id":"SAT-10-06-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A clock loses 3 minutes every hour. After 10 hours, how many minutes lost?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"30 minutes"},{"id":"b","text":"3 minutes"},{"id":"c","text":"33 minutes"},{"id":"d","text":"60 minutes"}],"correctOptionId":"a","explanation":"3 minutes/hour x 10 hours = 30 minutes lost.","difficulty":"Medium"},
  {"id":"SAT-10-06-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A job pays $12/hour for first 40 hours, $18/hour overtime. For 45 hours, total pay?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"$570"},{"id":"b","text":"$540"},{"id":"c","text":"$480"},{"id":"d","text":"$600"}],"correctOptionId":"a","explanation":"40 x 12 + 5 x 18 = 480 + 90 = $570.","difficulty":"Medium"},
  {"id":"SAT-10-06-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A rectangle's length is 3 more than twice its width. If perimeter is 54, what is width?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"8"},{"id":"b","text":"9"},{"id":"c","text":"7"},{"id":"d","text":"10"}],"correctOptionId":"a","explanation":"Width = w, length = 2w+3. 2(w + 2w+3) = 54 -> 6w+6 = 54 -> w = 8.","difficulty":"Hard"},
  {"id":"SAT-10-06-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A can fill a pool in 8 hours, B can empty it in 12 hours. Both open, how long to fill?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"24 hours"},{"id":"b","text":"20 hours"},{"id":"c","text":"10 hours"},{"id":"d","text":"4 hours"}],"correctOptionId":"a","explanation":"Net rate = 1/8 - 1/12 = 1/24. Time = 24 hours.","difficulty":"Hard"},
  {"id":"SAT-10-06-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A store marks up items 40% then offers 20% discount. Overall percent change?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"12% increase"},{"id":"b","text":"20% increase"},{"id":"c","text":"12% decrease"},{"id":"d","text":"8% increase"}],"correctOptionId":"a","explanation":"1.40 x 0.80 = 1.12. Overall 12% increase.","difficulty":"Hard"},
  {"id":"SAT-10-06-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"Two trains start 300 miles apart, approaching each other at 60 and 40 mph. Meeting time?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"3 hours"},{"id":"b","text":"5 hours"},{"id":"c","text":"6 hours"},{"id":"d","text":"2.5 hours"}],"correctOptionId":"a","explanation":"Relative speed = 60 + 40 = 100 mph. Time = 300/100 = 3 hours.","difficulty":"Hard"},
  {"id":"SAT-10-06-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"If 4 workers can build a wall in 6 days, how many workers needed in 3 days?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"8"},{"id":"b","text":"6"},{"id":"c","text":"12"},{"id":"d","text":"4"}],"correctOptionId":"a","explanation":"Work = 4 x 6 = 24 worker-days. For 3 days: 24/3 = 8 workers.","difficulty":"Hard"},
  {"id":"SAT-10-06-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A mixture is 30% alcohol. How much pure alcohol to add to get 50% in 10 liters?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"4 liters"},{"id":"b","text":"2 liters"},{"id":"c","text":"5 liters"},{"id":"d","text":"3 liters"}],"correctOptionId":"a","explanation":"Current alcohol = 3 liters. Let x = pure alcohol. (3+x)/(10+x) = 0.5 -> 3+x = 5+0.5x -> 0.5x = 2 -> x = 4.","difficulty":"Hard"},
  {"id":"SAT-10-06-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A rod is cut into two pieces. One piece is 4 cm longer than the other. Total 20 cm. Shorter piece?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"8 cm"},{"id":"b","text":"12 cm"},{"id":"c","text":"10 cm"},{"id":"d","text":"6 cm"}],"correctOptionId":"a","explanation":"x + (x+4) = 20 -> 2x = 16 -> x = 8.","difficulty":"Hard"},
  {"id":"SAT-10-06-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A car travels 200 km at 50 km/h, then 300 km at 60 km/h. Average speed?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"55.6 km/h"},{"id":"b","text":"55 km/h"},{"id":"c","text":"50 km/h"},{"id":"d","text":"57 km/h"}],"correctOptionId":"a","explanation":"Total distance = 500 km. Time = 200/50 + 300/60 = 4 + 5 = 9 hours. Avg = 500/9 = 55.6 km/h.","difficulty":"Hard"},
  {"id":"SAT-10-06-29","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"The product of two consecutive positive integers is 182. Smaller integer?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"13"},{"id":"b","text":"14"},{"id":"c","text":"12"},{"id":"d","text":"11"}],"correctOptionId":"a","explanation":"n(n+1) = 182. n^2 + n - 182 = 0. n = 13 (since 13 x 14 = 182).","difficulty":"Hard"},
  {"id":"SAT-10-06-30","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 6: Problem Solving Strategies","yearEC":"2024 E.C.","questionText":"A store sells notebooks for $3 and pens for $2. 10 items bought for $24. How many notebooks?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"4"},{"id":"b","text":"6"},{"id":"c","text":"5"},{"id":"d","text":"3"}],"correctOptionId":"a","explanation":"3n + 2(10-n) = 24 -> 3n + 20 - 2n = 24 -> n = 4.","difficulty":"Hard"},
  {"id":"SAT-10-07-01","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"In the passage, the author's main purpose is to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"inform readers about a topic"},{"id":"b","text":"entertain with a story"},{"id":"c","text":"persuade readers to act"},{"id":"d","text":"describe a person"}],"correctOptionId":"a","explanation":"Identifying main purpose is a key critical reading skill.","difficulty":"Easy"},
  {"id":"SAT-10-07-02","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The word 'substantial' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"considerable"},{"id":"b","text":"small"},{"id":"c","text":"temporary"},{"id":"d","text":"uncertain"}],"correctOptionId":"a","explanation":"Substantial means considerable in size, importance, or amount.","difficulty":"Easy"},
  {"id":"SAT-10-07-03","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"Which best describes the tone of this passage?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"objective and analytical"},{"id":"b","text":"angry and frustrated"},{"id":"c","text":"humorous and lighthearted"},{"id":"d","text":"sad and melancholy"}],"correctOptionId":"a","explanation":"Objective and analytical tone is common in academic passages.","difficulty":"Easy"},
  {"id":"SAT-10-07-04","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The passage suggests that the author most likely:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"supports the idea"},{"id":"b","text":"opposes the idea"},{"id":"c","text":"is neutral about the idea"},{"id":"d","text":"is confused about the idea"}],"correctOptionId":"a","explanation":"Inferring author's position requires analyzing evidence and language choices.","difficulty":"Easy"},
  {"id":"SAT-10-07-05","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"What is the best summary of this paragraph?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"main idea with key details"},{"id":"b","text":"every sentence restated"},{"id":"c","text":"author's biography"},{"id":"d","text":"unrelated facts"}],"correctOptionId":"a","explanation":"A good summary captures the main idea and essential supporting details.","difficulty":"Easy"},
  {"id":"SAT-10-07-06","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The word 'mitigate' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"reduce"},{"id":"b","text":"increase"},{"id":"c","text":"ignore"},{"id":"d","text":"create"}],"correctOptionId":"a","explanation":"Mitigate means to make less severe or painful.","difficulty":"Easy"},
  {"id":"SAT-10-07-07","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The passage is primarily organized as:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"cause and effect"},{"id":"b","text":"chronological order"},{"id":"c","text":"comparison"},{"id":"d","text":"problem and solution"}],"correctOptionId":"a","explanation":"Identifying text structure helps comprehension.","difficulty":"Easy"},
  {"id":"SAT-10-07-08","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The author uses the example of 'X' primarily to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"support a claim"},{"id":"b","text":"introduce a new topic"},{"id":"c","text":"contradict a point"},{"id":"d","text":"entertain the reader"}],"correctOptionId":"a","explanation":"Examples are used to support or illustrate claims.","difficulty":"Easy"},
  {"id":"SAT-10-07-09","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"Based on the passage, which statement is best supported?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"stated in the text"},{"id":"b","text":"contradicted by text"},{"id":"c","text":"unrelated to text"},{"id":"d","text":"opposite of text"}],"correctOptionId":"a","explanation":"Best-supported statements are directly backed by textual evidence.","difficulty":"Easy"},
  {"id":"SAT-10-07-10","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The word 'profound' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"deep"},{"id":"b","text":"shallow"},{"id":"c","text":"simple"},{"id":"d","text":"brief"}],"correctOptionId":"a","explanation":"Profound means very great or intense, or having deep insight.","difficulty":"Easy"},
  {"id":"SAT-10-07-11","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"Which is an example of author's bias?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"use of emotional language"},{"id":"b","text":"factual statistics"},{"id":"c","text":"expert quotes"},{"id":"d","text":"balanced argument"}],"correctOptionId":"a","explanation":"Emotional or loaded language indicates bias.","difficulty":"Medium"},
  {"id":"SAT-10-07-12","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The passage shifts from discussing X to Y in order to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"show contrast"},{"id":"b","text":"repeat information"},{"id":"c","text":"end the passage"},{"id":"d","text":"confuse readers"}],"correctOptionId":"a","explanation":"Shifts in focus often serve to contrast different ideas or perspectives.","difficulty":"Medium"},
  {"id":"SAT-10-07-13","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The word 'ambivalent' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"having mixed feelings"},{"id":"b","text":"certain"},{"id":"c","text":"excited"},{"id":"d","text":"angry"}],"correctOptionId":"a","explanation":"Ambivalent means having simultaneous conflicting feelings.","difficulty":"Medium"},
  {"id":"SAT-10-07-14","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The author would most likely agree with which statement?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"consistent with passage"},{"id":"b","text":"contradicts passage"},{"id":"c","text":"not addressed in passage"},{"id":"d","text":"opposite of passage"}],"correctOptionId":"a","explanation":"Infer author's likely agreement based on stated views and evidence.","difficulty":"Medium"},
  {"id":"SAT-10-07-15","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"What does the author imply but not directly state?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"inference from text"},{"id":"b","text":"explicit statement"},{"id":"c","text":"irrelevant detail"},{"id":"d","text":"contradiction"}],"correctOptionId":"a","explanation":"Implications are meanings not directly stated but suggested by the text.","difficulty":"Medium"},
  {"id":"SAT-10-07-16","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The function of the second paragraph is to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"provide supporting evidence"},{"id":"b","text":"introduce the topic"},{"id":"c","text":"conclude the argument"},{"id":"d","text":"contradict the first"}],"correctOptionId":"a","explanation":"Body paragraphs typically provide supporting evidence for the main claim.","difficulty":"Medium"},
  {"id":"SAT-10-07-17","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The word 'advocate' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"support publicly"},{"id":"b","text":"oppose privately"},{"id":"c","text":"ignore completely"},{"id":"d","text":"destroy utterly"}],"correctOptionId":"a","explanation":"Advocate means to publicly recommend or support.","difficulty":"Medium"},
  {"id":"SAT-10-07-18","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"Which evidence best supports the author's main claim?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"relevant and credible"},{"id":"b","text":"irrelevant data"},{"id":"c","text":"unverified opinion"},{"id":"d","text":"opposing evidence"}],"correctOptionId":"a","explanation":"Strong evidence is both relevant to the claim and from credible sources.","difficulty":"Medium"},
  {"id":"SAT-10-07-19","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The author's attitude toward the subject can best be described as:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"supportive"},{"id":"b","text":"hostile"},{"id":"c","text":"indifferent"},{"id":"d","text":"confused"}],"correctOptionId":"a","explanation":"Author's attitude is revealed through word choice and evidence selection.","difficulty":"Medium"},
  {"id":"SAT-10-07-20","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The passage would most likely appear in:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"a textbook"},{"id":"b","text":"a novel"},{"id":"c","text":"a poem"},{"id":"d","text":"a diary"}],"correctOptionId":"a","explanation":"The formal, informative style suggests a textbook or academic source.","difficulty":"Medium"},
  {"id":"SAT-10-07-21","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The word 'deteriorate' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"become worse"},{"id":"b","text":"improve"},{"id":"c","text":"stay the same"},{"id":"d","text":"disappear"}],"correctOptionId":"a","explanation":"Deteriorate means to become progressively worse.","difficulty":"Hard"},
  {"id":"SAT-10-07-22","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"Which choice best describes the structure of the passage?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"claim, evidence, counterclaim"},{"id":"b","text":"question, answer"},{"id":"c","text":"list of facts"},{"id":"d","text":"personal narrative"}],"correctOptionId":"a","explanation":"Argumentative passages often follow claim-evidence-counterclaim structure.","difficulty":"Hard"},
  {"id":"SAT-10-07-23","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The author addresses a counterargument in order to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"strengthen their position"},{"id":"b","text":"weaken their position"},{"id":"c","text":"confuse readers"},{"id":"d","text":"end the discussion"}],"correctOptionId":"a","explanation":"Addressing counterarguments demonstrates thorough analysis and strengthens the main claim.","difficulty":"Hard"},
  {"id":"SAT-10-07-24","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The phrase 'by and large' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"generally"},{"id":"b","text":"always"},{"id":"c","text":"never"},{"id":"d","text":"specifically"}],"correctOptionId":"a","explanation":"By and large means in general, on the whole.","difficulty":"Hard"},
  {"id":"SAT-10-07-25","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"Which assumption does the author make?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"readers share background knowledge"},{"id":"b","text":"readers know nothing"},{"id":"c","text":"readers disagree"},{"id":"d","text":"readers are experts"}],"correctOptionId":"a","explanation":"Authors often assume shared background knowledge with their audience.","difficulty":"Hard"},
  {"id":"SAT-10-07-26","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The word 'pragmatic' most nearly means:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"practical"},{"id":"b","text":"idealistic"},{"id":"c","text":"theoretical"},{"id":"d","text":"emotional"}],"correctOptionId":"a","explanation":"Pragmatic means dealing with things sensibly and realistically.","difficulty":"Hard"},
  {"id":"SAT-10-07-27","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The passage most strongly supports which conclusion?","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"logical inference"},{"id":"b","text":"opposite conclusion"},{"id":"c","text":"unrelated idea"},{"id":"d","text":"unsupported claim"}],"correctOptionId":"a","explanation":"Strongly supported conclusions follow logically from the evidence presented.","difficulty":"Hard"},
  {"id":"SAT-10-07-28","subject":"SAT","stream":"Common","chapter":"Grade 10 - Chapter 7: Critical Reading","yearEC":"2024 E.C.","questionText":"The author's use of statistics serves primarily to:","hasImage":false,"imagePlaceholder":"","options":[{"id":"a","text":"provide concrete evidence"},{"id":"b","text":"confuse readers"},{"id":"c","text":"entertain audience"},{"id":"d","text":"fill space"}],"correctOptionId":"a","explanation":"Statistics provide concrete, quantifiable evidence to support claims.","difficulty":"Hard"},
